import sys, json
d = json.load(sys.stdin)
for p in d.get('projects',[]):
  name = p['path'].split('/')[-2] if p['path'].endswith('.csproj') else p['path']
  for fw in p.get('frameworks',[]):
    for pkg in fw.get('topLevelPackages',[]):
      print(f\"{name:10} {pkg['id']:40} {pkg.get('requestedVersion',''):10} -> {pkg.get('resolvedVersion','')}\")
"

